from pyscipopt import Model, quicksum
import json

# Data
D = {
    1: {1: 1500, 2: 1000, 3: 2000, 4: 1200},
    2: {1: 1500, 2: 1500, 3: 1200, 4: 1500},
    3: {1: 1000, 2: 2000, 3: 1500, 4: 2500},
}
h = {1: 2, 2: 4, 3: 3}
C = 15000
penalty = {1: 20, 2: 20, 3: 10}
inv_cost = 5
end_inv = 150

products = [1, 2, 3]
quarters = [1, 2, 3, 4]

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables
x = {}
I = {}
L = {}
for p in products:
    for t in quarters:
        x[p, t] = m.addVar(vtype="C", lb=0, name=f"x_{p}_{t}")
        I[p, t] = m.addVar(vtype="C", lb=0, name=f"I_{p}_{t}")
        L[p, t] = m.addVar(vtype="C", lb=0, name=f"L_{p}_{t}")

# Balance constraints: I_{p,t} - L_{p,t} = I_{p,t-1} + x_{p,t} - D_{p,t}
for p in products:
    for t in quarters:
        prev_inv = I[p, t - 1] if t > 1 else 0
        m.addCons(I[p, t] - L[p, t] == prev_inv + x[p, t] - D[p][t], name=f"balance_{p}_{t}")

# Capacity constraints
for t in quarters:
    m.addCons(quicksum(h[p] * x[p, t] for p in products) <= C, name=f"capacity_{t}")

# Product I cannot be produced in Q2
m.addCons(x[1, 2] == 0, name="no_prod_I_Q2")

# End inventory constraints
for p in products:
    m.addCons(I[p, 4] >= end_inv, name=f"end_inv_{p}")

# Objective: minimize inventory cost + late delivery compensation
obj_terms = []
for p in products:
    for t in quarters:
        obj_terms.append(inv_cost * I[p, t])
        obj_terms.append(penalty[p] * L[p, t])

m.setObjective(quicksum(obj_terms), "minimize")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")

from pyscipopt import Model, quicksum
import math

# Data
n = 20
K = 5
Q = 200
s = 90
T_depot = 1236
M = 10000

coords = {
    0: (40, 50), 1: (45, 68), 2: (45, 70), 3: (42, 66), 4: (42, 68),
    5: (42, 65), 6: (40, 69), 7: (40, 66), 8: (38, 68), 9: (38, 70),
    10: (35, 66), 11: (35, 69), 12: (25, 85), 13: (22, 75), 14: (22, 85),
    15: (20, 80), 16: (20, 85), 17: (18, 75), 18: (15, 75), 19: (15, 80),
    20: (30, 50)
}

demand = {
    1: 10, 2: 30, 3: 10, 4: 10, 5: 10,
    6: 20, 7: 20, 8: 20, 9: 10, 10: 10,
    11: 10, 12: 20, 13: 30, 14: 10, 15: 40,
    16: 40, 17: 20, 18: 20, 19: 10, 20: 10
}

tw = {
    1: (912, 967), 2: (825, 870), 3: (65, 146), 4: (727, 782), 5: (15, 67),
    6: (621, 702), 7: (170, 225), 8: (255, 324), 9: (534, 605), 10: (357, 410),
    11: (448, 505), 12: (652, 721), 13: (30, 92), 14: (567, 620), 15: (384, 429),
    16: (475, 528), 17: (99, 148), 18: (179, 254), 19: (278, 345), 20: (10, 73)
}

nodes = list(range(n + 1))
C = list(range(1, n + 1))

# Precompute Euclidean distances
d = {}
for i in nodes:
    for j in nodes:
        if i != j:
            d[(i, j)] = math.sqrt((coords[i][0] - coords[j][0])**2 + (coords[i][1] - coords[j][1])**2)

# Model
m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Variables
x = {}
for k in range(K):
    for i in nodes:
        for j in nodes:
            if i != j:
                x[(i, j, k)] = m.addVar(vtype="B", name=f"x_{i}_{j}_{k}")

t = {}
for k in range(K):
    for i in nodes:
        t[(i, k)] = m.addVar(vtype="C", lb=0, ub=T_depot, name=f"t_{i}_{k}")

# Objective: minimize total distance traveled by all vehicles
m.setObjective(
    quicksum(d[(i, j)] * x[(i, j, k)] for k in range(K) for i in nodes for j in nodes if i != j),
    "minimize"
)

# C1: Each customer visited exactly once (by exactly one vehicle)
for i in C:
    m.addCons(
        quicksum(x[(j, i, k)] for k in range(K) for j in nodes if j != i) == 1,
        f"visit_{i}"
    )

# C2: At most one departure from depot per vehicle
for k in range(K):
    m.addCons(
        quicksum(x[(0, j, k)] for j in C) <= 1,
        f"dep_dep_{k}"
    )

# C3: At most one return to depot per vehicle
for k in range(K):
    m.addCons(
        quicksum(x[(i, 0, k)] for i in C) <= 1,
        f"dep_ret_{k}"
    )

# C3b: Depot flow balance – a vehicle that departs must return
for k in range(K):
    m.addCons(
        quicksum(x[(0, j, k)] for j in C) == quicksum(x[(i, 0, k)] for i in C),
        f"dep_bal_{k}"
    )

# C4: Flow conservation at each customer for each vehicle
for k in range(K):
    for i in C:
        m.addCons(
            quicksum(x[(j, i, k)] for j in nodes if j != i) ==
            quicksum(x[(i, j, k)] for j in nodes if j != i),
            f"flow_{i}_{k}"
        )

# C5: Capacity constraint – total demand on a route <= vehicle capacity
for k in range(K):
    m.addCons(
        quicksum(demand[i] * x[(j, i, k)] for i in C for j in nodes if j != i) <= Q,
        f"cap_{k}"
    )

# C6: Hard time window upper bound (active only when vehicle k visits customer i)
for k in range(K):
    for i in C:
        m.addCons(
            t[(i, k)] <= tw[i][1] + M * (1 - quicksum(x[(j, i, k)] for j in nodes if j != i)),
            f"tw_ub_{i}_{k}"
        )

# C6b: Hard time window lower bound (active only when vehicle k visits customer i)
for k in range(K):
    for i in C:
        m.addCons(
            t[(i, k)] >= tw[i][0] - M * (1 - quicksum(x[(j, i, k)] for j in nodes if j != i)),
            f"tw_lb_{i}_{k}"
        )

# C7: Time propagation from depot to first customer
for k in range(K):
    for i in C:
        m.addCons(
            t[(i, k)] >= d[(0, i)] - M * (1 - x[(0, i, k)]),
            f"tp_dep_{i}_{k}"
        )

# C8: Time propagation between customers (includes service time and travel)
for k in range(K):
    for i in C:
        for j in C:
            if i != j:
                m.addCons(
                    t[(j, k)] >= t[(i, k)] + s + d[(i, j)] - M * (1 - x[(i, j, k)]),
                    f"tp_{i}_{j}_{k}"
                )

# C9: Waiting constraint – service at i cannot start before tw[i][0],
#     so departure from i is at earliest tw[i][0]+s
for k in range(K):
    for i in C:
        for j in C:
            if i != j:
                m.addCons(
                    t[(j, k)] >= tw[i][0] + s + d[(i, j)] - M * (1 - x[(i, j, k)]),
                    f"wait_{i}_{j}_{k}"
                )

# C10: Vehicle must return to depot before the depot closes
for k in range(K):
    for i in C:
        m.addCons(
            t[(i, k)] + s + d[(i, 0)] <= T_depot + M * (1 - x[(i, 0, k)]),
            f"ret_{i}_{k}"
        )

# Note: Subtour elimination is handled implicitly by the time propagation
# constraints (C8/C9), which enforce strictly increasing time along any
# arc used by a vehicle, making cycles impossible. No MTZ constraint is
# needed (and is infeasible with wide time windows on bounded t variables).

# Solve
m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")

from pyscipopt import Model, quicksum

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Data
commodities = ['S', 'E', 'C', 'P']
prices = {'S': 500, 'E': 1500, 'C': 300, 'P': 1200}
import_cost = {'S': 250, 'E': 300, 'C': 50, 'P': 300}
labor = {'S': 6, 'E': 12, 'C': 6, 'P': 24}
prod_limit = {'E': 650000, 'P': 60000}
total_labor = 830000

# a[c][d] = units of commodity c required to produce 1 unit of commodity d
a = {
    'S': {'S': 0, 'E': 0.8, 'C': 0.01, 'P': 0.2},
    'E': {'S': 0.02, 'E': 0, 'C': 0.01, 'P': 0.03},
    'C': {'S': 0, 'E': 0.15, 'C': 0, 'P': 0.05},
    'P': {'S': 0.01, 'E': 0.11, 'C': 0.05, 'P': 0}
}

# Decision variables: total production of each commodity (continuous, >= 0)
x = {c: m.addVar(vtype="C", lb=0, name=f"x_{c}") for c in commodities}

# Objective: Maximize GDP
# GDP = sum_d [price[d] - import_cost[d] - sum_{c!=d} price[c]*a[c][d]] * x[d]
obj_coeffs = {}
for d in commodities:
    coeff = prices[d] - import_cost[d]
    for c in commodities:
        if c != d:
            coeff -= prices[c] * a[c][d]
    obj_coeffs[d] = coeff

obj = quicksum([obj_coeffs[d] * x[d] for d in commodities])
m.setObjective(obj, "maximize")

# Balance constraints: net export of each commodity >= 0
for c in commodities:
    m.addCons(x[c] - quicksum([a[c][d] * x[d] for d in commodities if d != c]) >= 0,
              name=f"balance_{c}")

# Production capacity limits
for c, lim in prod_limit.items():
    m.addCons(x[c] <= lim, name=f"limit_{c}")

# Total labor constraint (person-months)
m.addCons(quicksum([labor[c] * x[c] for c in commodities]) <= total_labor, name="labor")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")

from pyscipopt import Model, quicksum
import json

# Data
n = 4
cities = [1, 2, 3, 4]
dist = {
    (1, 2): 10, (1, 3): 20, (1, 4): 12,
    (2, 1): 10, (2, 3): 5,  (2, 4): 10,
    (3, 1): 20, (3, 2): 5,  (3, 4): 8,
    (4, 1): 15, (4, 2): 12, (4, 3): 8,
}

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables
x = {}
for i in cities:
    for j in cities:
        if i != j:
            x[(i, j)] = m.addVar(vtype="B", lb=0, ub=1, name=f"x_{i}{j}")

u = {}
for i in cities:
    u[i] = m.addVar(vtype="C", lb=1, ub=n, name=f"u_{i}")

# Objective: minimize total distance
m.setObjective(quicksum(dist[(i, j)] * x[(i, j)] for i in cities for j in cities if i != j), "minimize")

# Flow out constraints: each city has exactly one outgoing edge
for i in cities:
    m.addCons(quicksum(x[(i, j)] for j in cities if j != i) == 1, name=f"outflow_city{i}")

# Flow in constraints: each city has exactly one incoming edge
for i in cities:
    m.addCons(quicksum(x[(j, i)] for j in cities if j != i) == 1, name=f"inflow_city{i}")

# Subtour elimination (MTZ): applied only to non-depot city pairs
# The depot is city 1; edges to/from the depot do not require MTZ constraints
# because the depot is always on the tour and cannot form a subtour by itself.
depot = 1
non_depot = [i for i in cities if i != depot]
for i in non_depot:
    for j in non_depot:
        if i != j:
            m.addCons(u[i] - u[j] + n * x[(i, j)] <= n - 1, name=f"subtour_{i}{j}")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")
    # Print the route
    route = [depot]
    current = depot
    while True:
        for j in cities:
            if j != current and m.getVal(x[(current, j)]) > 0.5:
                route.append(j)
                current = j
                break
        if current == depot:
            break
    print(f"route: {' -> '.join(map(str, route))}")

from pyscipopt import Model, quicksum
import json

# Data
n = 2
d = [[10, 20],
     [30, 40]]
c = [[5, 8],
     [6, 7]]

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables
# x[i][p] = 1 if factory i is assigned to location p
x = {}
for i in range(n):
    for p in range(n):
        x[i, p] = m.addVar(name=f"x_{i}_{p}", vtype="B", lb=0, ub=1)

# y[i][j][p][q] = x[i][p] * x[j][q] for i != j, p != q
y = {}
for i in range(n):
    for j in range(n):
        if i == j:
            continue
        for p in range(n):
            for q in range(n):
                if p == q:
                    continue
                y[i, j, p, q] = m.addVar(name=f"y_{i}_{j}_{p}_{q}", vtype="B", lb=0, ub=1)

# Assignment constraints: each factory to exactly one location
for i in range(n):
    m.addCons(quicksum(x[i, p] for p in range(n)) == 1, name=f"assign_fac_{i}")

# Each location gets exactly one factory
for p in range(n):
    m.addCons(quicksum(x[i, p] for i in range(n)) == 1, name=f"assign_loc_{p}")

# Linearization constraints for y[i][j][p][q] = x[i][p] * x[j][q]
for i in range(n):
    for j in range(n):
        if i == j:
            continue
        for p in range(n):
            for q in range(n):
                if p == q:
                    continue
                m.addCons(y[i, j, p, q] <= x[i, p], name=f"lin1_{i}_{j}_{p}_{q}")
                m.addCons(y[i, j, p, q] <= x[j, q], name=f"lin2_{i}_{j}_{p}_{q}")
                m.addCons(y[i, j, p, q] >= x[i, p] + x[j, q] - 1, name=f"lin3_{i}_{j}_{p}_{q}")

# Objective: minimize total transportation cost
# Term 1: i=j, p=q -> d[i][i]*c[p][p]*x[i][p]
# Term 2: i!=j, p!=q -> d[i][j]*c[p][q]*y[i][j][p][q]
obj_terms = []
for i in range(n):
    for p in range(n):
        obj_terms.append(d[i][i] * c[p][p] * x[i, p])
for i in range(n):
    for j in range(n):
        if i == j:
            continue
        for p in range(n):
            for q in range(n):
                if p == q:
                    continue
                obj_terms.append(d[i][j] * c[p][q] * y[i, j, p, q])

m.setObjective(quicksum(obj_terms), "minimize")

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")

from pyscipopt import Model, quicksum
import json

# Data
total_space = 5000
rent_rate = 0.2

area = {1: 250, 2: 350, 3: 800, 4: 400, 5: 500}

# profit_per_store[i][k] = profit per store when there are k stores of type i
profit_per_store = {
    1: {1: 9, 2: 8, 3: 7},
    2: {1: 10, 2: 9},
    3: {1: 27, 2: 21, 3: 20},
    4: {1: 16, 2: 10},
    5: {1: 17, 2: 15, 3: 12},
}

# min/max number of shops per type
min_shops = {1: 1, 2: 1, 3: 1, 4: 0, 5: 1}
max_shops = {1: 3, 2: 2, 3: 3, 4: 2, 5: 3}

# Build model
m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables: y[i][k] = 1 if type i has exactly k shops
y = {}
for i in range(1, 6):
    for k in range(min_shops[i], max_shops[i] + 1):
        y[(i, k)] = m.addVar(vtype="B", name=f"y_{i}_{k}")

# Objective: maximize total rental income
# Total profit for type i with k shops = k * profit_per_store[i][k]
# Rent = 0.2 * total profit
obj_terms = []
for i in range(1, 6):
    for k in range(min_shops[i], max_shops[i] + 1):
        if k == 0:
            total_profit = 0
        else:
            total_profit = k * profit_per_store[i][k]
        obj_terms.append(rent_rate * total_profit * y[(i, k)])

m.setObjective(quicksum(obj_terms), "maximize")

# Constraint: exactly one k selected per store type
for i in range(1, 6):
    m.addCons(quicksum(y[(i, k)] for k in range(min_shops[i], max_shops[i] + 1)) == 1,
             name=f"select_type_{i}")

# Constraint: total area <= 5000
space_terms = []
for i in range(1, 6):
    for k in range(min_shops[i], max_shops[i] + 1):
        space_terms.append(area[i] * k * y[(i, k)])

m.addCons(quicksum(space_terms) <= total_space, name="space_limit")

# Solve
m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")
    for i in range(1, 6):
        for k in range(min_shops[i], max_shops[i] + 1):
            val = m.getVal(y[(i, k)])
            if val > 0.5:
                print(f"Type {i}: {k} shop(s)")

from pyscipopt import Model, quicksum
import json

# Data
proc_time = {
    'liquid': {'M1': 50, 'M2': 30},
    'solid':  {'M1': 24, 'M2': 33}
}
avail_hours = {'M1': 40, 'M2': 35}
initial_inv = {'liquid': 30, 'solid': 90}
demand = {'liquid': 75, 'solid': 95}
products = ['liquid', 'solid']
machines = ['M1', 'M2']

m = Model()
m.hideOutput()
m.setRealParam("limits/time", 570)

# Decision variables: lots to produce (continuous, fractional allowed)
x = {p: m.addVar(vtype="C", lb=0.0, name=f"x_{p}") for p in products}

# Objective: maximize total ending inventory
# ending_inv[p] = initial_inv[p] + x[p] - demand[p]
obj = quicksum(initial_inv[p] + x[p] - demand[p] for p in products)
m.setObjective(obj, "maximize")

# Machine capacity constraints (convert hours to minutes)
for mach in machines:
    cap_minutes = avail_hours[mach] * 60
    m.addCons(
        quicksum(proc_time[p][mach] * x[p] for p in products) <= cap_minutes,
        name=f"cap_{mach}"
    )

# Non-negative ending inventory (demand must be met)
for p in products:
    m.addCons(
        initial_inv[p] + x[p] - demand[p] >= 0,
        name=f"endinv_{p}"
    )

m.optimize()

st = m.getStatus()
print(f"status: {st}")
if m.getNSols() > 0:
    print(f"objective: {m.getObjVal()}")
